// Ported from the Node app's Sequelize model Book (first generated by tools/gen-efcore.mjs).
using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Metadata.Builders;
using SchoolERP.Domain.Entities;

namespace SchoolERP.Infrastructure.Persistence.Configurations;

internal sealed class BookConfiguration : IEntityTypeConfiguration<Book>
{
    public void Configure(EntityTypeBuilder<Book> builder)
    {
        builder.ToTable("books");
        builder.ConfigureAudit();
        builder.HasQueryFilter(e => !e.Delstatus);
        builder.HasKey(e => e.Id);
        builder.Property(e => e.Id).HasColumnName("id").UseIdentityColumn();
        builder.Property(e => e.Title).HasColumnName("title").HasColumnType("nvarchar(200)").HasMaxLength(200).IsRequired();
        builder.Property(e => e.Author).HasColumnName("author").HasColumnType("nvarchar(120)").HasMaxLength(120);
        builder.Property(e => e.CategoryId).HasColumnName("category_id");
        builder.Property(e => e.Isbn).HasColumnName("isbn").HasColumnType("nvarchar(30)").HasMaxLength(30);
        builder.Property(e => e.Copies).HasColumnName("copies");
        builder.Property(e => e.Available).HasColumnName("available");
        builder.HasIndex(e => e.Isbn).IsUnique();
        builder.HasOne(e => e.LibraryCategory).WithMany(p => p.Books).HasForeignKey(e => e.CategoryId).OnDelete(DeleteBehavior.NoAction);
    }
}
